using System;
using System.Linq;
using System.Collections.Generic;
namespace F1Manager {
// A tick is a sector opportunity, rather than a fresh random classification.
// RacePosition is authoritative. Only completed passes, pit losses and retirements change it.
public static class RaceDirector {
    public const double TickSeconds=.4;
    static readonly int[] opportunities={2,3,1,2,3,1,2,3,2,3,1,1,3,2,3,3,1,3,3,3,3,2,2};
    public static int TicksFor(Track track){int i=Array.IndexOf(Data.Tracks,track);return opportunities[i<0?0:i];}
    public static void Initialize(Career s,List<int> grid){var l=s.Weekend.Live;Powertrain.PrepareAI(s);l.TickRace=true;l.TicksPerLap=TicksFor(Data.Tracks[s.Round]);var ordered=l.Entries.OrderBy(e=>{int i=grid.IndexOf(e.Id);return i<0?100+e.Id:i;}).ToList();if(l.Name=="Гонка")ordered=ordered.OrderBy(e=>Powertrain.Car(s,e).GridPenalty?1:0).ToList();for(int i=0;i<ordered.Count;i++){var e=ordered[i];e.RacePosition=i+1;e.RaceTime=i*.7;e.Total=e.RaceTime;e.Garage=false;e.Status="На решётке";if(l.Name=="Гонка"&&Powertrain.Car(s,e).GridPenalty){Powertrain.Car(s,e).GridPenalty=false;l.Log.Insert(0,Engine.Person(s,e.Id).Name+": штраф за агрегат — старт с конца решётки.");}}}
    public static void MigrateLive(Career s){var l=s.Weekend.Live;var order=Engine.Order(s);var progress=order.ToDictionary(e=>e.Id,e=>e.Lap+(e.LapDuration>0?1-e.Remaining/e.LapDuration:0));double leading=progress.Values.Max();Initialize(s,order.Select(e=>e.Id).ToList());l.RaceTick=l.Entries.Max(e=>e.Lap)*l.TicksPerLap;foreach(var e in l.Entries){e.RaceTime=e.Finished&&e.FinishTime>0?e.FinishTime:l.Elapsed+Math.Max(0,leading-progress[e.Id])*Data.Tracks[s.Round].BaseLap;e.Total=e.RaceTime;}l.Paused=false;}
    public static bool Advance(Career s,double seconds,bool automatic){var l=s.Weekend.Live;l.TickAccumulator+=seconds;double duration=Data.Tracks[s.Round].BaseLap/l.TicksPerLap;bool incident=false;while(l.TickAccumulator>=duration&&!l.Finished){if(l.AwaitingEvent&&!automatic)break;l.TickAccumulator-=duration;if(automatic)l.AwaitingEvent=false;incident|=Step(s,automatic);if(l.AwaitingEvent&&!automatic)break;}return incident;}
    public static void Event(Career s,string flag,string message,int laps){var l=s.Weekend.Live;l.Flag=flag;l.FlagTicks=Math.Max(1,laps*l.TicksPerLap);Engine.Incident(s,message+"  Выберите: пит-стоп или продолжаем.");}
    public static void Continue(Career s){var l=s.Weekend.Live;l.AwaitingEvent=false;l.Paused=false;}
    static double TyreLife(string tyre){return tyre=="S"?22:tyre=="H"?48:tyre=="M"?34:38;}
    public static double Pace(Career s,Entry e){var l=s.Weekend.Live;double time=Engine.LapTime(s,l,e);double oldWear=e.StintLaps/(e.Tyre=="S"?17.0:e.Tyre=="M"?29.0:e.Tyre=="H"?43.0:30)*(.65+Data.Tracks[s.Round].Wear*.1)*(1+(80-CarModel.Metric(Engine.Team(s,e.Team),5))*.005)*(1+Math.Max(0,CarModel.Profile(Data.Tracks[s.Round]).TyreHeat-CarModel.Metric(Engine.Team(s,e.Team),7))*.009);time-=Math.Pow(Math.Max(0,oldWear-.45),2)*2.4;time+=Math.Pow(Math.Max(0,e.TyreWear/100-.30),2)*7+Math.Max(0,e.TyreWear-85)*.12;time+=e.EngineMode==2?-.55:e.EngineMode==0?.75:0;time+=e.DrivingMode==2?-.48:e.DrivingMode==0?.65:0;return Math.Max(55,time+Powertrain.PaceLoss(s,e));}
    public static bool Step(Career s,bool automatic=false){var l=s.Weekend==null?null:s.Weekend.Live;if(l==null||!l.TickRace||l.Finished||l.Paused||l.AwaitingEvent&&!automatic)return false;if(automatic)l.AwaitingEvent=false;bool eventOccurred=false;if(l.Flag=="RED"){l.Flag="SC";l.FlagTicks=l.TicksPerLap;Engine.Incident(s,"Рестарт за автомобилем безопасности. Можно изменить решение по пит-стопу.");return true;}
        var track=Data.Tracks[s.Round];double fraction=1.0/l.TicksPerLap;bool neutral=l.Flag!="GREEN";l.RaceTick++;l.Elapsed+=track.BaseLap*fraction*(neutral?1.35:1);var ordered=Engine.Order(s);double leaderTime=ordered.FirstOrDefault(e=>!e.Dnf)==null?0:ordered.First(e=>!e.Dnf).RaceTime;
        foreach(var e in ordered){e.PittedThisTick=false;if(e.Dnf||e.Finished)continue;e.PreviousGap=e.RaceTime-leaderTime;if(e.PassCooldown>0)e.PassCooldown--;if(e.Team!=s.Player){e.EngineMode=Powertrain.Car(s,e).Condition[0]<28?0:1;e.DrivingMode=e.TyreWear>75?0:1;}
            double pace=Pace(s,e);if(neutral)pace=track.BaseLap*(l.Flag=="SC"?1.45:1.25)+(l.Flag=="SC"?0:(pace-track.BaseLap)*.15);e.RaceTime+=pace*fraction;e.TickLapTime+=pace*fraction;e.Total=e.RaceTime;e.LapDuration=pace;e.Remaining=pace*(1-(l.RaceTick%l.TicksPerLap)/(double)l.TicksPerLap);double tyreFactor=(e.DrivingMode==2?1.45:e.DrivingMode==0?.65:1)*(neutral?.48:1);var team=Engine.Team(s,e.Team);double thermal=1+Math.Max(0,CarModel.Profile(track).TyreHeat-CarModel.Metric(team,7))*.009;double preservation=1+(80-CarModel.Metric(team,5))*.007;e.TyreWear=Engine.Clamp(e.TyreWear+100/TyreLife(e.Tyre)*(.65+track.Wear*.10)*thermal*preservation*tyreFactor*fraction,0,100);Powertrain.Wear(s,e,fraction*(neutral?.55:1));e.Status=neutral?l.Flag:"На трассе";
            if(l.RaceTick%l.TicksPerLap==0){e.Lap++;e.StintLaps++;e.Last=e.TickLapTime;e.TickLapTime=0;e.Best=Math.Min(e.Best,e.Last);if(e.Lap>=l.TargetLaps){e.Finished=true;e.FinishTime=e.RaceTime;e.Status="Финиш";continue;}}
            // Resource exhaustion is deterministic; incidental faults depend on reliability and mode.
            var units=Powertrain.Car(s,e);int broken=Array.FindIndex(units.Condition,x=>x<=0);double failure=(.00015+(100-CarModel.Metric(team,8))*.000016+Math.Max(0,25-units.Condition.Min())*.00010)*fraction*(e.EngineMode==2?1.5:1);
            if(broken>=0||Engine.Rand(s)<failure){e.Dnf=true;e.Status="Сход";e.Reason=broken>=0?"Ресурс исчерпан: "+Powertrain.Names[broken]:"Техническая неисправность";if(l.Flag=="GREEN"){Event(s,"VSC",Engine.Person(s,e.Id).Name+": "+e.Reason+". VSC для эвакуации машины.",1);eventOccurred=true;}continue;}
            if(!neutral&&Engine.Rand(s)<.00025*fraction*(e.DrivingMode==2?1.8:1)){e.Dnf=true;e.Status="Сход";e.Reason="Авария / контакт";bool red=Engine.Rand(s)<.16;Event(s,red?"RED":"SC",Engine.Person(s,e.Id).Name+": авария. "+(red?"КРАСНЫЙ ФЛАГ — заезд остановлен.":"SAFETY CAR на трассе."),red?1:2);eventOccurred=true;}
        }
        // Process stops before passes, so a pit lane loss can legitimately cost several places.
        foreach(var e in ordered.Where(e=>!e.Dnf&&!e.Finished)){var plan=e.Team==s.Player?Engine.PlanFor(s,e.Id):Engine.DefaultPlan(s,e.Plan);int next=e.ScheduledStops<plan.Stops.Count?plan.Stops[e.ScheduledStops]:int.MaxValue;bool planned=e.Lap>=next;bool weather=(e.Team!=s.Player||automatic)&&((l.Weather=="Дождь"&&e.Tyre!="I"&&e.Tyre!="W")||(l.Weather=="Сухо"&&(e.Tyre=="I"||e.Tyre=="W")));bool due=l.RaceTick%l.TicksPerLap==0;if(e.PitRequested||due&&(planned||weather)){string tyre=e.PitRequested?new[]{"S","M","H","I","W"}[e.NextTyre]:weather?(l.Weather=="Дождь"?"I":"M"):plan.Tyres[Math.Min(e.ScheduledStops+1,plan.Tyres.Count-1)];if(automatic&&l.Weather=="Дождь"&&tyre!="I"&&tyre!="W")tyre="I";if(automatic&&l.Weather=="Сухо"&&(tyre=="I"||tyre=="W"))tyre="M";double loss=(l.Flag=="SC"?12:l.Flag=="VSC"?15:22)+2.5+(95-Engine.Quality(s,e.Team,2))*.04;e.RaceTime+=loss;e.Total=e.RaceTime;e.Tyre=tyre;e.TyreWear=0;e.StintLaps=0;e.Stops++;if(planned)e.ScheduledStops++;e.PitRequested=false;e.PittedThisTick=true;e.Status="Пит-стоп → "+tyre;l.Log.Insert(0,Engine.Clock(l.Elapsed)+"  "+Engine.Person(s,e.Id).Name+": "+tyre+", потеря "+loss.ToString("0.0")+" с.");}}
        var active=ordered.Where(e=>!e.Dnf).ToList(); // Preserve order except for actual pit lane losses.
        for(int i=active.Count-2;i>=0;i--)if(active[i].PittedThisTick){var p=active[i];int j=i;while(j+1<active.Count&&active[j+1].RaceTime<p.RaceTime){active[j]=active[j+1];active[j+1]=p;j++;}}
        var passed=new HashSet<int>();for(int i=1;i<active.Count;i++){var front=active[i-1];var rear=active[i];if(front.Finished||rear.Finished)continue;double gap=rear.RaceTime-front.RaceTime;if(neutral){double minimum=l.Flag=="SC"?.55:.15;rear.RaceTime=Math.Max(front.RaceTime+minimum,l.Flag=="SC"?rear.RaceTime-Math.Max(0,gap-minimum)*.35:rear.RaceTime);continue;}if(gap>=.15)continue;double advantage=Pace(s,front)-Pace(s,rear);double skill=(Engine.Person(s,rear.Id).Rating-Engine.Person(s,front.Id).Rating)*.003;double speed=(CarModel.Metric(Engine.Team(s,rear.Team),4)-CarModel.Metric(Engine.Team(s,front.Team),4))*.003;double chance=Engine.Clamp((.08+advantage*.11+skill+speed+(rear.DrivingMode-1)*.04)*(l.TicksPerLap==1?.50:l.TicksPerLap==3?1.15:1),.005,.65);bool pass=!passed.Contains(front.Id)&&!passed.Contains(rear.Id)&&rear.PassCooldown==0&&advantage>(l.TicksPerLap==1?.25:.10)&&Engine.Rand(s)<chance;if(pass){rear.RaceTime=Math.Min(rear.RaceTime,front.RaceTime-.24);active[i-1]=rear;active[i]=front;rear.PassCooldown=2;front.PassCooldown=2;passed.Add(rear.Id);passed.Add(front.Id);l.Log.Insert(0,Engine.Clock(l.Elapsed)+"  "+Engine.Person(s,rear.Id).Name+" обгоняет "+Engine.Person(s,front.Id).Name+".");}else rear.RaceTime=front.RaceTime+.18;}
        for(int i=0;i<active.Count;i++){active[i].RacePosition=i+1;active[i].Total=active[i].RaceTime;if(active[i].Finished)active[i].FinishTime=active[i].RaceTime;}int rank=active.Count+1;foreach(var e in ordered.Where(e=>e.Dnf))e.RacePosition=rank++;
        if(!l.WeatherChanged&&l.Elapsed>=l.WeatherAt&&(l.Weather=="Дождь"||WeatherModel.AllowsRain(s))){l.WeatherChanged=true;l.Weather=l.Weather=="Дождь"?"Сухо":"Дождь";s.Weekend.Weather=l.Weather;if(l.Weather=="Дождь")s.Weekend.RainAffected=true;Engine.Incident(s,"Погода меняется: "+l.Weather+". Выберите шины и решение по пит-стопу.");eventOccurred=true;}
        if(l.Flag!="GREEN"&&!eventOccurred&&--l.FlagTicks<=0){l.Flag="GREEN";l.FlagTicks=0;l.Log.Insert(0,Engine.Clock(l.Elapsed)+"  ЗЕЛЁНЫЙ ФЛАГ — гонка возобновлена.");}
        if(l.Log.Count>80)l.Log.RemoveRange(80,l.Log.Count-80);if(l.Entries.All(e=>e.Finished||e.Dnf))Engine.Finish(s);return eventOccurred;
    }
    public static void Validate(Career s){var l=s.Weekend==null?null:s.Weekend.Live;if(l==null||!l.TickRace)return;if(l.TargetLaps<=0||l.TargetLaps>100||l.TicksPerLap<1||l.TicksPerLap>3||l.RaceTick<0||l.RaceTick>400||!new[]{"GREEN","SC","VSC","RED"}.Contains(l.Flag)||l.Entries.Any(e=>e.EngineMode<0||e.EngineMode>2||e.DrivingMode<0||e.DrivingMode>2||e.RacePosition<1||e.RacePosition>l.Entries.Count||double.IsNaN(e.RaceTime)||double.IsInfinity(e.RaceTime)||e.RaceTime<0||double.IsNaN(e.TyreWear)||e.TyreWear<0||e.TyreWear>100)||l.Entries.Select(e=>e.RacePosition).Distinct().Count()!=l.Entries.Count)throw new Exception("Повреждены данные интерактивной гонки.");}
}
}
